CREATE TABLE IF NOT EXISTS public.cbb_ncaa_results(season text NOT NULL,winner_id text NOT NULL,loser_id text NOT NULL,day_num integer NOT NULL,opening_round integer NOT NULL DEFAULT 0 CHECK(opening_round IN(0,1)),source_note text NOT NULL,PRIMARY KEY(season,winner_id,loser_id));CREATE INDEX IF NOT EXISTS cbb_ncaa_results_winner ON public.cbb_ncaa_results(season,winner_id);CREATE INDEX IF NOT EXISTS cbb_ncaa_results_loser ON public.cbb_ncaa_results(season,loser_id);ALTER TABLE public.cbb_ncaa_results ENABLE ROW LEVEL SECURITY;REVOKE ALL ON public.cbb_ncaa_results FROM anon, authenticated;